-- EVT lua patch for soccer_training_inplay_menu (common/script/lua/menu/soccer_training_inplay_menu_0.00.00.lua.bin). Graft hud_layout. Generated by research/scripts/menu_assemble.py (build --out patches) from research/grafts/; do not edit by hand.
-- ===== EVT hud_layout inplay BEGIN =====
-- EVT hud_layout, soccer_inplay_menu (+ its twins soccer_battle / soccer_training / soccer_zigzag_dribble_training
-- _inplay_menu: same include and globals, the loader picks the folder by the opened path, which was wrong on
-- 2026-09-29: one inplay VM was given the zigzag folder, which had no patches) and soccer_setplay_prev_menu (the restart menu after a goal, own
-- copy of the same layers) (docs/game/ui-redesign.md §11.1z5): the D-pad guides
-- of the coach AI (layer soccer00_67_change_ai_mode_button: instance 1 «Modo Comandante» / «Modo Manual», always
-- there; instance 0 bench request and 2 spectator, only in Commander mode) move from the bottom left to the top
-- centre, just under the scoreboard, stacked downwards (1, then 0, then 2), with the square blue plate of «Pase alto»
-- (soccer08_08 cmd_base01) instead of the rounded text-sized pill. The «can't use it» error bubble
-- (soccer00_58_common_error_message) goes under the stack. Visibility is NOT touched (retail, or whoever hides it).
-- Layout: the three guides hang from soccer00_66_change_ai_mode_button_attach (anchored bottom-left, x from the left,
-- y up from the bottom): _atc_ai_guide01..03 at (102, 141 / 198 / 255), plate from the locator to the right (width
-- set by the text, 122..400), 44 high; the error bubble from _atc_error01 (261, 258), centred on it.
-- Engine calls only from OnSetupLayer / OnOpenLayer / PostStep.

EVT_HL_CMDR_X = 960               -- centre x of the guides, layout units from the left (screen centre)
EVT_HL_CMDR_HALF_W = 137          -- half the plate width of «Modo Comandante» (the plate grows with the text)
EVT_HL_CMDR_TOP = 165             -- centre of the first guide, layout units DOWN from the top (the clock ends at ~127)
EVT_HL_CMDR_GAP = 57              -- distance between stacked guides (retail)
EVT_HL_CMDR_SQUARE = true         -- square blue plate instead of the pill
EVT_HL_CMDR_ERROR_BELOW = 1       -- error bubble this many gaps under the lowest guide
EVT_HL_SCREEN_H = 1080

local HLC_ATTACH = 1132565342 --[[soccer00_66_change_ai_mode_button_attach]]
local HLC_GUIDE = 2446662467 --[[soccer00_67_change_ai_mode_button]]
local HLC_ERROR = 3087830238 --[[soccer00_58_common_error_message]]
local HLC_LOC_X = 102
local HLC_LOC_Y = {141, 198, 255} --[[instances 0, 1, 2]]
local HLC_ERR_X, HLC_ERR_Y = 261, 258
local HLC_CMND_POS = 1389957207
local HLC_CMND_SWAP = 558735651
local HLC_ATLAS_0808 = 1822283221 --[[#/menu/00_soccer/soccer08/soccer08_08/<LG>/soccer08_08.g4tx]]
local HLC_PLATE = 2905228853 --[[cmd_base01]]
local HLC_SLOT = 3394469048 --[[ai_guide_base01: nine-slice pill of soccer00_67]]
local hlc_swapped = false

local function HLC_Cmd(...)
  if type(funcLuaMenuCommand) == "function" then
    return pcall(funcLuaMenuCommand, ...)
  end
  return false
end

local function HLC_Pack(...)
  return {n = select("#", ...), ...}
end

-- attach layer offset: instance 1's locator lands at the top slot
local function HLC_AttachOffset()
  local ax = EVT_HL_CMDR_X - EVT_HL_CMDR_HALF_W - HLC_LOC_X
  local ay = (EVT_HL_SCREEN_H - EVT_HL_CMDR_TOP) - HLC_LOC_Y[2]
  return ax, ay
end

local function HLC_Swap()
  hlc_swapped = true
  if not EVT_HL_CMDR_SQUARE then
    return
  end
  for i = 0, 2 do
    HLC_Cmd(HLC_CMND_SWAP, HLC_GUIDE, HLC_ATLAS_0808, HLC_PLATE, HLC_SLOT, 0, i)
  end
end

local function HLC_Place()
  local ax, ay = HLC_AttachOffset()
  local top = HLC_LOC_Y[2] + ay
  HLC_Cmd(HLC_CMND_POS, HLC_ATTACH, ax, ay, 0, 0)
  -- instance 0 is already one gap under instance 1; instance 2 (retail above) goes two gaps under it
  HLC_Cmd(HLC_CMND_POS, HLC_GUIDE, 0, 0, 0, 0)
  HLC_Cmd(HLC_CMND_POS, HLC_GUIDE, 0, 0, 0, 1)
  HLC_Cmd(HLC_CMND_POS, HLC_GUIDE, 0, (top - 2 * EVT_HL_CMDR_GAP) - (HLC_LOC_Y[3] + ay), 0, 2)
  local ey = top - (2 + EVT_HL_CMDR_ERROR_BELOW) * EVT_HL_CMDR_GAP
  HLC_Cmd(HLC_CMND_POS, HLC_ERROR, EVT_HL_CMDR_X - (HLC_ERR_X + ax), ey - (HLC_ERR_Y + ay), 0, 0)
end

local function HLC_Wrap(name, after)
  local prev = rawget(_ENV, name)
  if type(prev) ~= "function" then
    return
  end
  rawset(_ENV, name, function(...)
    local r = HLC_Pack(prev(...))
    pcall(after, ...)
    return table.unpack(r, 1, r.n)
  end)
end

local function HLC_OnLayer(a1)
  if a1 == HLC_GUIDE then
    HLC_Swap()
  end
  if a1 == HLC_ATTACH or a1 == HLC_GUIDE or a1 == HLC_ERROR then
    HLC_Place()
  end
end

HLC_Wrap("OnSetupLayer", HLC_OnLayer)
HLC_Wrap("OnOpenLayer", HLC_OnLayer)
local function HLC_Frame()
  if not hlc_swapped then
    HLC_Swap()
  end
  HLC_Place()
end
-- soccer_inplay_menu has PostStep (include), soccer_setplay_prev_menu has Step: whichever the menu defines
HLC_Wrap("PostStep", HLC_Frame)
HLC_Wrap("Step", HLC_Frame)
-- ===== EVT hud_layout inplay END =====
